add_action( 'wp', 'perfectpixel_move_jetpack_sharing_setup' );

function perfectpixel_move_jetpack_sharing_setup() {
	if ( ! function_exists( 'sharing_display' ) || ! function_exists( 'is_product' ) || ! is_product() ) {
		return;
	}
	remove_filter( 'the_content', 'sharing_display', 19 );
	remove_filter( 'the_excerpt', 'sharing_display', 19 );
	add_action( 'woocommerce_single_product_summary', 'perfectpixel_move_jetpack_sharing_output', 35 );
}

function perfectpixel_move_jetpack_sharing_output() {
	echo sharing_display( '', false ); // Jetpack returns its own escaped markup.
}
